parameters.jsCode:
const emb = $json.embeddings;
const vector = Array.isArray(emb[0]) ? emb[0] : emb;

return [{
  json: {
    question: $('Set - Normalizar entrada').first().json.question,
    searchQuery: $('Code - Detectar intención').first().json.searchQuery,
    session_id: $('Set - Normalizar entrada').first().json.session_id,
    vector,
    vector_length: Array.isArray(vector) ? vector.length : -1,
    first_values: Array.isArray(vector) ? vector.slice(0, 5) : [],
    intent: $('Code - Detectar intención').first().json.intent || "general"
  }
}];

const qdrantBody = $json.body || {};
const results = Array.isArray(qdrantBody.result) ? qdrantBody.result : [];
const intent = $('Code - Detectar intención').first().json.intent || "general";
const question = ($('Set - Normalizar entrada').first().json.question || "").toLowerCase();

// ─── DETECCIÓN DE PREGUNTA DE SEGUIMIENTO ───────────────────────────────────
const esSeguimiento = (
  question.includes("esos") || question.includes("esas") ||
  question.includes("ese") || question.includes("esa") ||
  question.includes("alguno de") || question.includes("alguna de") ||
  question.includes("de ellos") || question.includes("de ellas") ||
  question.includes("cuál de") || question.includes("cuáles de") ||
  question.includes("hay alguno") || question.includes("hay alguna") ||
  question.includes("también") || question.includes("además")
);

// Si es pregunta de seguimiento, intentar extraer keywords del contexto anterior
// Los resultados de Qdrant ya incluyen lo que se recuperó — si hay chunks de oferta
// con keywords útiles, los propagamos al boost
const keywordsContextoAnterior = [];
if (esSeguimiento && intent === "oferta") {
  // Buscar en los chunks recuperados si hay menciones de informática
  for (const r of results) {
    const texto = (r.payload?.pageContent || "").toLowerCase();
    if (/informátic|inform[aá]tic|daw|dam|asir|smr|ciberseguridad|python/.test(texto)) {
      keywordsContextoAnterior.push("informatica");
      break;
    }
  }
}
// ─────────────────────────────────────────────────────────────────────────────

const requestedEtapas = [];
if (question.includes("bachillerato")) requestedEtapas.push("bachillerato");
if (
  question.includes("formación profesional") ||
  question.includes("formacion profesional") ||
  question.includes(" fp") ||
  question.includes("ciclos formativos")
) {
  requestedEtapas.push("fp");
}

const uniqueRequestedEtapas = [...new Set(requestedEtapas)];

const rawChunks = results.map((item, index) => {
  const payload = item.payload || {};
  return {
    original_index: index + 1,
    score: item.score ?? 0,
    source: payload.documento || payload.document || `doc_${index + 1}`,
    text: (payload.pageContent || "").trim(),
    tipo: (payload.tipo || "").toString().toLowerCase(),
    etapa: (payload.etapa || "").toString().toLowerCase(),
    curso: (payload.curso || "").toString().toLowerCase()
  };
}).filter(chunk => chunk.text.length > 0);

function isCompatibleWithIntent(chunk, intent) {
  const haystack = (chunk.source + " " + chunk.text).toLowerCase();

  if (intent === "matricula") {
    if (chunk.tipo && chunk.tipo !== "matricula") return false;
    if (/admisi[oó]n extraordinaria|vacantes|solicitud|petici[oó]n/i.test(haystack)) return false;
  }
  if (intent === "admision") {
    if (chunk.tipo && chunk.tipo !== "admision") return false;
  }
  if (intent === "oferta") {
    if (chunk.tipo && chunk.tipo !== "oferta") return false;
  }
  if (intent === "calendario") {
    if (chunk.tipo && chunk.tipo !== "calendario") return false;
  }
  return true;
}

function isCompatibleWithEtapa(chunk, requestedEtapas) {
  if (requestedEtapas.length === 0) return true;
  if (!chunk.etapa) return false;
  return requestedEtapas.includes(chunk.etapa);
}

function keywordBoost(chunk, intent) {
  const haystack = (chunk.source + " " + chunk.text).toLowerCase();
  let boost = 0;

  if (intent === "matricula") {
    if (/matr[ií]cul|formaliz/.test(haystack)) boost += 0.15;
    if (/admisi[oó]n|vacantes|solicitud/.test(haystack)) boost -= 0.12;
  } else if (intent === "admision") {
    if (/admisi[oó]n|solicitud/.test(haystack)) boost += 0.15;
    if (/matr[ií]cul|formaliz/.test(haystack)) boost -= 0.05;
  } else if (intent === "oferta") {
    if (/oferta|ciclos|formaci[oó]n profesional|grado medio|grado superior/.test(haystack)) boost += 0.15;
    if (/calendario|matr[ií]cul|admisi[oó]n/.test(haystack)) boost -= 0.05;
    // Boost adicional si venimos de contexto de informática
    if (keywordsContextoAnterior.includes("informatica")) {
      if (/informátic|daw|dam|asir|smr|ciberseguridad|python/.test(haystack)) boost += 0.20;
    }
  } else if (intent === "calendario") {
    if (/calendario|pruebas extraordinarias|evaluaci[oó]n|junio|septiembre/.test(haystack)) boost += 0.15;
  }

  if (uniqueRequestedEtapas.length > 0 && chunk.etapa && uniqueRequestedEtapas.includes(chunk.etapa)) {
    boost += 0.10;
  }

  return boost;
}

function mentionsOtherStages(chunk, requestedEtapas) {
  if (requestedEtapas.length === 0) return false;
  const text = (chunk.source + " " + chunk.text).toLowerCase();
  const detected = [];
  if (/infantil|primaria/.test(text)) detected.push("primaria");
  if (/eso|educación secundaria obligatoria|educacion secundaria obligatoria/.test(text)) detected.push("eso");
  if (/bachillerato/.test(text)) detected.push("bachillerato");
  if (/formación profesional|formacion profesional|ciclos formativos|grado medio|grado superior/.test(text)) detected.push("fp");
  const uniqueDetected = [...new Set(detected)];
  return uniqueDetected.some(stage => !requestedEtapas.includes(stage));
}

const filtered = rawChunks
  .filter(chunk => isCompatibleWithIntent(chunk, intent))
  .filter(chunk => isCompatibleWithEtapa(chunk, uniqueRequestedEtapas))
  .filter(chunk => !mentionsOtherStages(chunk, uniqueRequestedEtapas));

const preferredByIntent = intent === "matricula"
  ? filtered.filter(chunk => chunk.tipo === "matricula")
  : filtered;

const baseSet = preferredByIntent.length > 0
  ? preferredByIntent
  : (filtered.length > 0 ? filtered : rawChunks.filter(chunk => isCompatibleWithEtapa(chunk, uniqueRequestedEtapas)));

const rescored = baseSet.map(chunk => ({
  ...chunk,
  adjustedScore: chunk.score + keywordBoost(chunk, intent)
}));

rescored.sort((a, b) => b.adjustedScore - a.adjustedScore);

const perSourceCount = {};
const selected = [];

for (const chunk of rescored) {
  const count = perSourceCount[chunk.source] || 0;
  if (count < 2 && selected.length < 4) {
    selected.push(chunk);
    perSourceCount[chunk.source] = count + 1;
  }
}

if (selected.length < 4) {
  for (const chunk of rescored) {
    const alreadyIncluded = selected.some(
      s => s.source === chunk.source && s.text === chunk.text
    );
    if (!alreadyIncluded) {
      selected.push(chunk);
    }
    if (selected.length >= 6) break;
  }
}

const finalChunks = selected.map((chunk, idx) => ({
  index: idx + 1,
  score: chunk.score,
  adjustedScore: chunk.adjustedScore,
  source: chunk.source,
  tipo: chunk.tipo,
  etapa: chunk.etapa,
  curso: chunk.curso,
  text: chunk.text.slice(0, 1800)
}));

const sourceSummary = [...new Set(finalChunks.map(c => c.source))].join(" | ");

const lowConfidence = finalChunks.length === 0 || (
  intent === "matricula" &&
  !finalChunks.some(c => c.tipo === "matricula")
);

const context = finalChunks
  .map(chunk =>
    `[${chunk.index}] Fuente: ${chunk.source}\nTipo: ${chunk.tipo || "desconocido"} | Etapa: ${chunk.etapa || "desconocida"} | Curso: ${chunk.curso || "desconocido"}\n${chunk.text}`
  )
  .join("\n\n---\n\n");

return [{
  json: {
    question: $('Set - Normalizar entrada').first().json.question,
    session_id: $('Set - Normalizar entrada').first().json.session_id,
    intent,
    lowConfidence,
    sourceSummary,
    requestedEtapas: uniqueRequestedEtapas,
    context,
    chunks: finalChunks,
    total_chunks: finalChunks.length
  }
}];

const question = $('Set - Normalizar entrada').first().json.question || '';
const session_id = $('Set - Normalizar entrada').first().json.session_id || '';
const answer = $('AI Agent').first().json.output || '';
const chunks = $('Code - Construir contexto').first().json.chunks || [];

const sources = chunks.map(c => ({
  source: c.source,
  score: c.score
}));

return [{
  json: {
    question,
    answer: answer.trim(),
    session_id,
    sources
  }
}];

const q = (($json.question || "") + "").toLowerCase();
let intent = "general";
let searchQuery = $json.question;

// MATRÍCULA
if (
  q.includes("matrícul") || q.includes("matricula") ||
  q.includes("inscripci") || q.includes("inscribir") ||
  q.includes("formaliz") || q.includes("plazo") ||
  q.includes("cuándo empieza") || q.includes("cuando empieza")
) {
  intent = "matricula";
  searchQuery = "fechas matrícula plazos inscripción formalización";

// ADMISIÓN
} else if (
  q.includes("admis") || q.includes("acceso") ||
  q.includes("nota de corte") || q.includes("requisito") ||
  q.includes("puedo entrar") || q.includes("plaza") ||
  q.includes("solicitud")
) {
  intent = "admision";
  searchQuery = "admisión acceso requisitos nota de corte solicitud plaza";

// OFERTA FORMATIVA
} else if (
  q.includes("ofert") || q.includes("ciclos") ||
  q.includes("ciclo") || q.includes("grado medio") ||
  q.includes("grado superior") || q.includes("formación profesional") ||
  q.includes("formacion profesional") || q.includes(" fp") ||
  q.includes("daw") || q.includes("dam") || q.includes("asir") ||
  q.includes("ciberseguridad") || q.includes("diseño") ||
  q.includes("informática") || q.includes("informatica") ||
  q.includes("especialización") || q.includes("especializacion") ||
  q.includes("qué estudia") || q.includes("que estudia") ||
  q.includes("qué se estudia") || q.includes("que se estudia") ||
  q.includes("enseñanza") || q.includes("ensenanza")
) {
  intent = "oferta";
  searchQuery = "qué ciclos ofrece el centro formación profesional";

// CALENDARIO
} else if (
  q.includes("calendario") || q.includes("pruebas extraordinarias") ||
  q.includes("evaluación") || q.includes("evaluacion") ||
  q.includes("examen") || q.includes("trimestre") ||
  q.includes("vacaciones") || q.includes("festivo") ||
  q.includes("inicio de curso") || q.includes("fin de curso") ||
  q.includes("junio") || q.includes("septiembre")
) {
  intent = "calendario";
  searchQuery = "calendario escolar fechas evaluación trimestres vacaciones inicio fin curso";

// BECAS Y AYUDAS
} else if (
  q.includes("beca") || q.includes("ayuda") ||
  q.includes("subvenci") || q.includes("releo") ||
  q.includes("dispositivo") || q.includes("ordenador") ||
  q.includes("tablet") || q.includes("transporte")
) {
  intent = "becas";
  searchQuery = "becas ayudas subvenciones RELEO dispositivos transporte alumnado";

// HORARIOS Y SECRETARÍA
} else if (
  q.includes("horario") || q.includes("secretar") ||
  q.includes("atención") || q.includes("atencion") ||
  q.includes("contacto") || q.includes("teléfono") ||
  q.includes("telefono") || q.includes("correo") ||
  q.includes("email") || q.includes("dirección") ||
  q.includes("cómo contactar") || q.includes("como contactar")
) {
  intent = "secretaria";
  searchQuery = "horario secretaría atención público contacto teléfono correo";

// CONVIVENCIA Y NORMAS
} else if (
  q.includes("convivencia") || q.includes("norma") ||
  q.includes("reglamento") || q.includes("rri") ||
  q.includes("sanción") || q.includes("sancion") ||
  q.includes("expulsión") || q.includes("expulsion") ||
  q.includes("consejo escolar")
) {
  intent = "convivencia";
  searchQuery = "reglamento régimen interior normas convivencia sanciones consejo escolar";

// ORIENTACIÓN Y TUTORÍAS  
} else if (
  q.includes("orientaci") || q.includes("tutor") ||
  q.includes("tutoría") || q.includes("tutoria") ||
  q.includes("orientador") || q.includes("bachillerato") ||
  q.includes("universidad") || q.includes("selectividad") ||
  q.includes("evau") || q.includes("pbau")
) {
  intent = "orientacion";
  searchQuery = "orientación tutorías bachillerato universidad EVAU acceso";
}

return [{
  json: {
    ...$json,
    intent,
    searchQuery
  }
}];

const intent = $json.intent || "general";

const intentsSinPDF = ["matricula", "admision", "calendario", "becas", "secretaria"];

let qdrantFilter = null;

if (intent === "oferta") {
  qdrantFilter = {
    must: [
      { key: "origen", match: { value: "ies" } },
      { key: "tipo", match: { value: "oferta" } }
    ],
    must_not: [
      { key: "documento", match: { value: "Propuesta Curricular ESO 2025-26" } },
      { key: "documento", match: { value: "Propuesta Curricular Bachillerato 2025-26" } }
    ]
  };
} else if (intentsSinPDF.includes(intent)) {
  qdrantFilter = {
    must_not: [
      { key: "documento", match: { value: "Propuesta Curricular ESO 2025-26" } },
      { key: "documento", match: { value: "Propuesta Curricular Bachillerato 2025-26" } },
      { key: "documento", match: { value: "Reglamento de Régimen Interior" } }
    ]
  };
}

return [{
  json: {
    ...$json,
    qdrantFilter
  }
}];

